// Moon-Phase Lamp — four lights show the moon's phase; a button steps to the next phase.
// The lights only glow when the room is dark.

#ifndef VB_CAL_LDR1_DARK
#define VB_CAL_LDR1_DARK 300
#endif
#ifndef VB_CAL_LDR1_HYST
#define VB_CAL_LDR1_HYST 40
#endif

const uint8_t LED_PINS[4] = {2, 3, 4, 5};   // left to right
const uint8_t BUTTON_PIN = 7;               // button to GND, internal pull-up
const uint8_t LIGHT_PIN = A0;               // photoresistor to 5V, 10k to GND
const unsigned long DEBOUNCE_MS = 30;

// bit 3 = leftmost light, bit 0 = rightmost light
const uint8_t PHASE_MASK[8] = {0b0000, 0b0001, 0b0011, 0b0111, 0b1111, 0b1110, 0b1100, 0b1000};
const char* const PHASE_NAME[8] = {
  "new moon", "waxing crescent", "first quarter", "waxing gibbous",
  "full moon", "waning gibbous", "last quarter", "waning crescent"
};

uint8_t phase = 4;          // start at full moon
bool dark = false;
bool buttonStable = HIGH;
bool buttonLastRaw = HIGH;
unsigned long buttonChangedAt = 0;

void showLights() {
  uint8_t mask = dark ? PHASE_MASK[phase] : 0;
  for (uint8_t i = 0; i < 4; i++) {
    digitalWrite(LED_PINS[i], (mask & (0b1000 >> i)) ? HIGH : LOW);
  }
}

void setup() {
  for (uint8_t i = 0; i < 4; i++) {
    pinMode(LED_PINS[i], OUTPUT);
    digitalWrite(LED_PINS[i], LOW);
  }
  pinMode(BUTTON_PIN, INPUT_PULLUP);
  Serial.begin(115200);
  dark = analogRead(LIGHT_PIN) < VB_CAL_LDR1_DARK;
  Serial.print(F("moon-lamp ready, phase="));
  Serial.print(PHASE_NAME[phase]);
  Serial.println(dark ? F(", dark") : F(", bright"));
  showLights();
}

void loop() {
  unsigned long now = millis();

  // Debounced button: act once on the press edge.
  bool raw = digitalRead(BUTTON_PIN);
  if (raw != buttonLastRaw) {
    buttonLastRaw = raw;
    buttonChangedAt = now;
  }
  if (raw != buttonStable && now - buttonChangedAt >= DEBOUNCE_MS) {
    buttonStable = raw;
    if (buttonStable == LOW) {
      phase = (phase + 1) % 8;
      Serial.print(F("phase="));
      Serial.println(PHASE_NAME[phase]);
      showLights();
    }
  }

  // Room light with hysteresis.
  int level = analogRead(LIGHT_PIN);
  if (!dark && level < VB_CAL_LDR1_DARK) {
    dark = true;
    Serial.println(F("room dark: lamp on"));
    showLights();
  } else if (dark && level > VB_CAL_LDR1_DARK + VB_CAL_LDR1_HYST) {
    dark = false;
    Serial.println(F("room bright: lamp off"));
    showLights();
  }
}
